select * from (
select
rep.REPORTUUID, rep.TERMID, rep.REPORTTYPE, rep.STARTDATE, rep.ENDDATE, rep.ISSUE_PARTY_ID,
rep.ISSUE_PARTY_NAME,
rep.REPORTFREQU, rep.REPORT_ORG_NAME, rep.SOCIAL_CREDIT_CODE, rep.FIN_INSTITUTION_CODE, rep.PROD_VARIETY,
rep.PERSON_LIABLE, rep.CONTACT, rep.REPORT_DATE, rep.SUBMIT_TIME, rep.CHB_SUBMIT_DEADLINE, rep.SUBMIT_DEADLINE,
rep.SUBMIT_FEEDBACK_STATUS, rep.STATUS, rep.SEND_STATUS, rep.STATUS_DATE, rep.CREATE_USER, rep.CREATE_TIME,
rep.UPDATE_USER, rep.UPDATE_TIME, rep.ORG_CODE, rep.DEPT_CODE,
rep.CREATE_DEPT,nvl(t2.pbc_code,rep.PBC_ACCOUNT_ID)PBC_ACCOUNT_ID,
rep.PBC_ACCOUNT_ID as pbcAccountIdShow,t2.pbc_code
, pra.ACCOUNT_ID
from PBC_REPORT rep
left join PBC_PRD_ACCOUNT_SUB pra on pra.PBC_ACCOUNT_ID=rep.PBC_ACCOUNT_ID
LEFT JOIN(
SELECT
inside_prod_id,
pbc_code
FROM
pbc_prod_assetpool_code
WHERE
status='E'
AND code_type='02'
)t2 ON t2.inside_prod_id=pra.ACCOUNT_ID



            #{items,jdbcType=VARCHAR}




            #{items,jdbcType=VARCHAR}





            #{items.pbcAccountId,jdbcType=VARCHAR}




            #{items,jdbcType=VARCHAR}





            #{item,jdbcType=VARCHAR}




            #{item,jdbcType=VARCHAR}




            #{item,jdbcType=VARCHAR}




            #{submitFeedbackStatus,jdbcType=VARCHAR}



        and to_char(rep.STATUS_DATE,'yyyy-MM-dd') >= #{statusDateStart,jdbcType=VARCHAR}


        and to_char(rep.STATUS_DATE,'yyyy-MM-dd') <= #{statusDateEnd,jdbcType=VARCHAR}


        and rep.termid >= #{submitDateStart,jdbcType=VARCHAR}


        and rep.termid <= #{submitDateEnd,jdbcType=VARCHAR}


        and to_char(rep.SUBMIT_TIME,'yyyy-MM-dd') >= #{submitTimeStart,jdbcType=VARCHAR}


        and to_char(rep.SUBMIT_TIME,'yyyy-MM-dd') <= #{submitTimeEnd,jdbcType=VARCHAR}


        AND to_char(rep.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') >= #{submitDeadLineStart,jdbcType=VARCHAR}


        and to_char(rep.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') <= #{submitDeadLineEnd,jdbcType=VARCHAR}


        and rep.termid = #{termid,jdbcType=VARCHAR}


        and to_char(rep.UPDATE_TIME,'yyyy-MM-dd') = #{updateTime}







        and rep.CREATE_DEPT in ( select dept_code from sys_department sd1
        start with sd1.dept_code = #{createDept,jdbcType=VARCHAR}
        connect by prior sd1.dept_code = sd1.upper_dept_code )



    and rep.reporttype = 'ONEPRD_ASSET_DEBT'

)


ORDER BY CHB_SUBMIT_DEADLINE ASC, UPDATE_TIME DESC

